-- Local dev seed data: one guest, public, mixed-content session so the
-- dashboard/session-view pages have something real to render against
-- before the actual upload flow (Milestone 2) exists.
--
-- Note: owner_token_hash here is a placeholder SHA-256 of the string "demo"
-- purely for local testing -- never a real secret. Real tokens are
-- generated by lib/auth/owner-token.ts (Milestone 2).

insert into sessions (id, owner_token_hash, title, visibility)
values (
  '00000000-0000-0000-0000-000000000001',
  encode(digest('demo', 'sha256'), 'hex'),
  'Demo transfer package',
  'public'
);

insert into items (session_id, kind, title, order_index, text_content, text_language, status)
values (
  '00000000-0000-0000-0000-000000000001',
  'text',
  'setup-notes.md',
  0,
  '# Setup notes' || chr(10) || chr(10) || 'Run `npm install` then `npm run dev`.',
  'markdown',
  'ready'
);

